mapper.select:
SELECT p.*, t.name AS tenant_name FROM sys_post p LEFT JOIN sys_tenant t ON t.id = p.tenant_id AND t.is_deleted = 0 WHERE p.is_deleted = 0
AND p.tenant_id = #{tenantId}
AND (p.name LIKE CONCAT('%', #{request.keyword}, '%') OR p.code LIKE CONCAT('%', #{request.keyword}, '%'))
ORDER BY p.${request.safeSortField()} ${request.safeSortOrder()}
ORDER BY p.sort ASC
